"""FR-53: exact scores generated by pinned FIRST JavaScript, not guessed ratings."""

import json
from pathlib import Path

import pytest

from vulnscan.assessment.cvss import parse_vector, score, validate
from vulnscan.contracts import Severity
from vulnscan.contracts.assessment import CVSSAssessment

FIXTURE = json.loads(Path(__file__).with_name("cvss4_first_vectors.json").read_text())
BASE = FIXTURE["cases"][0]["vector"]


@pytest.mark.parametrize("case", FIXTURE["cases"], ids=lambda case: case["vector"])
def test_matches_pinned_first_base_and_contextual_scores(case):
    result = score(case["vector"])
    assert result.base_score == case["base_score"]
    assert result.overall_score == case["overall_score"]
    assert result.missing == []


def test_incomplete_base_is_unknown_not_zero():
    result = score("CVSS:4.0/AV:N/AC:L")
    assert result.base_score is None and result.qualitative is None
    assert {"AT", "PR", "UI", "VC", "VI", "VA", "SC", "SI", "SA"}.issubset(result.missing)
    assert any("SC" in error for error in validate("CVSS:4.0/AV:N/AC:L"))


@pytest.mark.parametrize(
    "vector",
    [
        BASE + "/S:U",
        BASE + "/UNKNOWN:H",
        BASE.replace("UI:N", "UI:X"),
        BASE.replace("AT:N", "AT:Q"),
        BASE.replace("AV:N/AC:L", "AC:L/AV:N"),
        BASE + "/E:A/E:P",
        BASE + "/",
        BASE + "/U:purple",
    ],
)
def test_invalid_v4_metrics_or_order_are_rejected_by_scoring(vector):
    with pytest.raises(ValueError):
        score(vector)
    assert validate(vector)


def test_active_user_interaction_is_valid_and_safety_is_supplemental():
    assert validate(BASE.replace("UI:N", "UI:A")) == []
    assert parse_vector(BASE + "/S:P")["S"] == "P"
    assert score(BASE + "/S:P").base_score == score(BASE).base_score
    assert score(BASE + "/E:P").nomenclature == "CVSS-BT"
    assert score(BASE + "/MAV:P").nomenclature == "CVSS-BE"
    assert score(BASE + "/E:P/MSI:S").nomenclature == "CVSS-BTE"


def test_assessment_recomputes_model_numbers_from_valid_vector():
    cvss = CVSSAssessment(vector=BASE, base_score=1.0, qualitative=Severity.LOW)
    assert cvss.base_score == 9.3 and cvss.qualitative == Severity.CRITICAL
    assert cvss.overall_score == 9.3 and cvss.nomenclature == "CVSS-B"
    assert cvss.calculation_source == "FIRST CVSS v4.0"
    cvss.base_score = 1.0
    assert cvss.base_score == 9.3


@pytest.mark.parametrize("vector", [BASE.replace("/UI:N", "/UI:A"), BASE + "/E:P/MSI:S"])
def test_assessment_accepts_valid_v4_forms_without_legacy_prefix_regex(vector):
    assert CVSSAssessment(vector=vector).base_score is not None


def test_assessment_rejects_missing_mandatory_subsequent_impacts():
    with pytest.raises(ValueError):
        CVSSAssessment(vector=BASE.split("/SC:")[0])
